INSERT INTO glossary_terms (slug, term, alt_names, short_definition, body, sources, status, published_at) VALUES ($q$avaliacao-neuropsicologica$q$, $q$Avaliação neuropsicológica$q$, ARRAY[$q$Exame neuropsicológico$q$,$q$Testagem neuropsicológica$q$]::text[], $q$Processo estruturado que investiga funções cognitivas, como atenção, memória, linguagem e funções executivas, por meio de entrevista e testes padronizados.$q$, $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Os resultados são interpretados junto com a história de vida, a rotina e a queixa da pessoa, e costumam ser registrados em um "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/glossario/laudo-psicologico","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"laudo"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":" apresentado em uma "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/glossario/devolutiva","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"devolutiva"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"A literatura indica que a avaliação acrescenta informação útil ao cuidado de pessoas com risco de alteração cognitiva, com evidência mais forte em comprometimento cognitivo leve, demência e traumatismo craniano. Ela não decide um diagnóstico sozinha."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Veja "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/avaliacao-neuropsicologica","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"como funciona a avaliação neuropsicológica na Vila Madalena"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":" e "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/perguntas/quanto-tempo-dura-a-avaliacao-neuropsicologica","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"quanto tempo ela dura"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"."}]}]}}$q$::jsonb, $q$["Donders J. The incremental value of neuropsychological assessment: a critical review. Clin Neuropsychol. 2020;34(1):56-87. doi:10.1080/13854046.2019.1575471","Watt S, Crowe SF. Examining the beneficial effect of neuropsychological assessment on adult patient outcomes: a systematic review. Clin Neuropsychol. 2018;32(3):368-390. doi:10.1080/13854046.2017.1414885"]$q$::jsonb, 'published', now()) ON CONFLICT (slug) DO NOTHING;
INSERT INTO glossary_terms (slug, term, alt_names, short_definition, body, sources, status, published_at) VALUES ($q$neuropsicologia$q$, $q$Neuropsicologia$q$, '{}'::text[], $q$Área da Psicologia que estuda cognição, emoções, personalidade e comportamento em sua relação com o funcionamento do cérebro.$q$, $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"No Brasil, o Conselho Federal de Psicologia reconhece a Neuropsicologia como especialidade da Psicologia desde a Resolução CFP nº 2/2004."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Na prática clínica, uma de suas aplicações é a "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/glossario/avaliacao-neuropsicologica","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"avaliação neuropsicológica"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"."}]}]}}$q$::jsonb, $q$["Conselho Federal de Psicologia. Experiência brasileira em neuropsicologia é apresentada pelo CFP em congresso global (sobre a Resolução CFP nº 2/2004). site.cfp.org.br."]$q$::jsonb, 'published', now()) ON CONFLICT (slug) DO NOTHING;
INSERT INTO glossary_terms (slug, term, alt_names, short_definition, body, sources, status, published_at) VALUES ($q$funcoes-executivas$q$, $q$Funções executivas$q$, ARRAY[$q$Controle executivo$q$]::text[], $q$Conjunto de habilidades que permitem planejar, resistir a impulsos, manter o foco e se adaptar a mudanças.$q$, $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"As funções centrais costumam ser descritas como inibição (autocontrole e controle da interferência), "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/glossario/memoria-de-trabalho","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"memória de trabalho"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":" e flexibilidade cognitiva."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Estresse, falta de sono, solidão e falta de exercício físico podem prejudicar essas funções, o que é um dos motivos para interpretar qualquer resultado de teste junto com o contexto de vida da pessoa."}]}]}}$q$::jsonb, $q$["Diamond A. Executive functions. Annu Rev Psychol. 2013;64:135-168. doi:10.1146/annurev-psych-113011-143750"]$q$::jsonb, 'published', now()) ON CONFLICT (slug) DO NOTHING;
INSERT INTO glossary_terms (slug, term, alt_names, short_definition, body, sources, status, published_at) VALUES ($q$atencao$q$, $q$Atenção$q$, ARRAY[$q$Atenção seletiva$q$,$q$Sistema atencional$q$]::text[], $q$Capacidade de manter o alerta, orientar-se para o que é relevante e controlar a resposta ao que acontece ao redor.$q$, $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"A pesquisa descreve redes cerebrais distintas relacionadas ao alerta, à orientação e ao controle executivo, que se desenvolvem da infância em diante."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Queixas de atenção têm muitas causas possíveis. Uma "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/glossario/avaliacao-neuropsicologica","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"avaliação neuropsicológica"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":" pode ajudar a descrever como essa função se apresenta em cada pessoa."}]}]}}$q$::jsonb, $q$["Petersen SE, Posner MI. The attention system of the human brain: 20 years after. Annu Rev Neurosci. 2012;35:73-89. doi:10.1146/annurev-neuro-062111-150525"]$q$::jsonb, 'published', now()) ON CONFLICT (slug) DO NOTHING;
INSERT INTO glossary_terms (slug, term, alt_names, short_definition, body, sources, status, published_at) VALUES ($q$memoria-de-trabalho$q$, $q$Memória de trabalho$q$, ARRAY[$q$Memória operacional$q$]::text[], $q$Capacidade de manter uma informação em mente e trabalhar mentalmente com ela, por exemplo ao fazer uma conta de cabeça.$q$, $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"É considerada uma das "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/glossario/funcoes-executivas","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"funções executivas"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":" centrais e dá apoio ao controle de impulsos, porque é preciso manter o objetivo em mente para saber o que é relevante."}]}]}}$q$::jsonb, $q$["Diamond A. Executive functions. Annu Rev Psychol. 2013;64:135-168. doi:10.1146/annurev-psych-113011-143750","Baddeley A. Working memory: theories, models, and controversies. Annu Rev Psychol. 2012;63:1-29. doi:10.1146/annurev-psych-120710-100422"]$q$::jsonb, 'published', now()) ON CONFLICT (slug) DO NOTHING;
INSERT INTO glossary_terms (slug, term, alt_names, short_definition, body, sources, status, published_at) VALUES ($q$laudo-psicologico$q$, $q$Laudo psicológico$q$, ARRAY[$q$Laudo neuropsicológico$q$]::text[], $q$Documento escrito que resulta de um processo de avaliação psicológica e serve para subsidiar decisões relacionadas à demanda que originou a avaliação.$q$, $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Pela Resolução CFP nº 6/2019, o laudo tem seis itens: identificação, descrição da demanda, procedimento, análise, conclusão e referências."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"A entrega acontece em uma "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/glossario/devolutiva","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"entrevista devolutiva"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"."}]}]}}$q$::jsonb, $q$["Conselho Federal de Psicologia. Resolução CFP nº 6, de 29 de março de 2019: elaboração de documentos escritos."]$q$::jsonb, 'published', now()) ON CONFLICT (slug) DO NOTHING;
INSERT INTO glossary_terms (slug, term, alt_names, short_definition, body, sources, status, published_at) VALUES ($q$devolutiva$q$, $q$Devolutiva$q$, ARRAY[$q$Entrevista devolutiva$q$,$q$Sessão de devolutiva$q$]::text[], $q$Encontro em que a psicóloga ou o psicólogo apresenta e conversa sobre os resultados de uma avaliação e o documento produzido.$q$, $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"A Resolução CFP nº 6/2019 prevê a entrevista devolutiva na entrega do "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/glossario/laudo-psicologico","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"laudo psicológico"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":" e de relatórios, o que dá espaço para esclarecer dúvidas sobre o conteúdo."}]}]}}$q$::jsonb, $q$["Conselho Federal de Psicologia. Resolução CFP nº 6, de 29 de março de 2019: elaboração de documentos escritos."]$q$::jsonb, 'published', now()) ON CONFLICT (slug) DO NOTHING;
INSERT INTO glossary_terms (slug, term, alt_names, short_definition, body, sources, status, published_at) VALUES ($q$satepsi$q$, $q$SATEPSI$q$, ARRAY[$q$Sistema de Avaliação de Testes Psicológicos$q$]::text[], $q$Sistema do Conselho Federal de Psicologia que avalia a qualidade técnico-científica de instrumentos psicológicos para uso profissional.$q$, $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"A lista pública fica em satepsi.cfp.org.br. Pela Resolução CFP nº 31/2022, o uso profissional de testes psicológicos é privativo de psicólogas e psicólogos, e sua aplicação, correção e interpretação devem seguir o manual técnico."}]}]}}$q$::jsonb, $q$["Conselho Federal de Psicologia. Resolução CFP nº 31, de 15 de dezembro de 2022: diretrizes para a avaliação psicológica e regulamentação do SATEPSI."]$q$::jsonb, 'published', now()) ON CONFLICT (slug) DO NOTHING;
INSERT INTO glossary_terms (slug, term, alt_names, short_definition, body, sources, status, published_at) VALUES ($q$tdah$q$, $q$TDAH$q$, ARRAY[$q$Transtorno do déficit de atenção com hiperatividade$q$]::text[], $q$Transtorno do neurodesenvolvimento diagnosticado por um profissional habilitado, que documenta os critérios clínicos em entrevista com a pessoa ou seus cuidadores.$q$, $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"O consenso internacional de 2021 estima a ocorrência em 5,9% dos jovens e 2,5% dos adultos e afirma que o diagnóstico não pode ser feito apenas com escalas, testes neuropsicológicos ou exames de imagem do cérebro."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Veja também "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/perguntas/a-avaliacao-neuropsicologica-diagnostica-tdah","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"a avaliação neuropsicológica diagnostica TDAH?"}]}]}]}}$q$::jsonb, $q$["Faraone SV et al. The World Federation of ADHD International Consensus Statement: 208 evidence-based conclusions about the disorder. Neurosci Biobehav Rev. 2021;128:789-818. doi:10.1016/j.neubiorev.2021.01.022"]$q$::jsonb, 'published', now()) ON CONFLICT (slug) DO NOTHING;
INSERT INTO glossary_terms (slug, term, alt_names, short_definition, body, sources, status, published_at) VALUES ($q$tea$q$, $q$Transtorno do espectro autista$q$, ARRAY[$q$TEA$q$,$q$Autismo$q$]::text[], $q$Termo que descreve um conjunto de diferenças precoces na comunicação social e comportamentos sensório-motores repetitivos, associado a forte componente genético e a outras causas.$q$, $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"As necessidades de apoio variam muito de uma pessoa para outra e ao longo da vida. A literatura destaca a importância de ajuda oportuna e individualizada às famílias e de serviços também para adultos."}]}]}}$q$::jsonb, $q$["Lord C et al. Autism spectrum disorder. Lancet. 2018;392(10146):508-520. doi:10.1016/S0140-6736(18)31129-2"]$q$::jsonb, 'published', now()) ON CONFLICT (slug) DO NOTHING;
INSERT INTO glossary_terms (slug, term, alt_names, short_definition, body, sources, status, published_at) VALUES ($q$comprometimento-cognitivo-leve$q$, $q$Comprometimento cognitivo leve$q$, ARRAY[$q$CCL$q$]::text[], $q$Síndrome definida por declínio cognitivo maior do que o esperado para a idade e a escolaridade, sem interferência notável nas atividades do dia a dia.$q$, $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Algumas pessoas permanecem estáveis ou voltam ao normal com o tempo, enquanto outras evoluem para demência, por isso o acompanhamento é parte do cuidado. É uma das condições em que a "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/glossario/avaliacao-neuropsicologica","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"avaliação neuropsicológica"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":" tem evidência mais forte de utilidade."}]}]}}$q$::jsonb, $q$["Gauthier S et al. Mild cognitive impairment. Lancet. 2006;367(9518):1262-1270. doi:10.1016/S0140-6736(06)68542-5","Donders J. The incremental value of neuropsychological assessment: a critical review. Clin Neuropsychol. 2020;34(1):56-87. doi:10.1080/13854046.2019.1575471"]$q$::jsonb, 'published', now()) ON CONFLICT (slug) DO NOTHING;
INSERT INTO glossary_terms (slug, term, alt_names, short_definition, body, sources, status, published_at) VALUES ($q$dislexia$q$, $q$Dislexia$q$, ARRAY[$q$Dislexia do desenvolvimento$q$]::text[], $q$Transtorno do neurodesenvolvimento caracterizado por reconhecimento de palavras lento e impreciso.$q$, $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Foi descrita em todas as culturas estudadas. A explicação neuropsicológica mais aceita envolve dificuldades fonológicas, que interagem com outros fatores cognitivos de risco."}]}]}}$q$::jsonb, $q$["Peterson RL, Pennington BF. Developmental dyslexia. Lancet. 2012;379(9830):1997-2007. doi:10.1016/S0140-6736(12)60198-6"]$q$::jsonb, 'published', now()) ON CONFLICT (slug) DO NOTHING;
INSERT INTO glossary_terms (slug, term, alt_names, short_definition, body, sources, status, published_at) VALUES ($q$psicoterapia$q$, $q$Psicoterapia$q$, ARRAY[$q$Terapia psicológica$q$]::text[], $q$Tratamento conduzido por profissional habilitado, baseado na relação de trabalho com a pessoa, para compreender e modificar o que mantém o sofrimento.$q$, $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"A pesquisa mostra associação consistente entre a "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/glossario/alianca-terapeutica","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"aliança terapêutica"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":" e os resultados, tanto presencialmente quanto pela internet. Fatores comuns às abordagens, como empatia e expectativas, também são importantes."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Veja "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/perguntas/como-funciona-a-psicoterapia","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"como funciona a psicoterapia"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":" e a página de "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/psicoterapia","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"psicoterapia individual"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"."}]}]}}$q$::jsonb, $q$["Flückiger C et al. The alliance in adult psychotherapy: a meta-analytic synthesis. Psychotherapy. 2018;55(4):316-340. doi:10.1037/pst0000172","Wampold BE. How important are the common factors in psychotherapy? An update. World Psychiatry. 2015;14(3):270-277. doi:10.1002/wps.20238"]$q$::jsonb, 'published', now()) ON CONFLICT (slug) DO NOTHING;
INSERT INTO glossary_terms (slug, term, alt_names, short_definition, body, sources, status, published_at) VALUES ($q$alianca-terapeutica$q$, $q$Aliança terapêutica$q$, ARRAY[$q$Aliança de trabalho$q$]::text[], $q$Qualidade da colaboração entre a pessoa e o profissional na psicoterapia, incluindo o vínculo e o acordo sobre objetivos e tarefas.$q$, $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Uma meta-análise de 295 estudos, com mais de 30 mil pacientes, encontrou associação positiva entre aliança e resultado na psicoterapia presencial (r = 0,278) e pela internet (r = 0,275). A associação não indica, sozinha, o que acontecerá em um caso específico."}]}]}}$q$::jsonb, $q$["Flückiger C et al. The alliance in adult psychotherapy: a meta-analytic synthesis. Psychotherapy. 2018;55(4):316-340. doi:10.1037/pst0000172"]$q$::jsonb, 'published', now()) ON CONFLICT (slug) DO NOTHING;
INSERT INTO glossary_terms (slug, term, alt_names, short_definition, body, sources, status, published_at) VALUES ($q$analise-do-comportamento$q$, $q$Análise do Comportamento$q$, ARRAY[$q$Terapia analítico-comportamental$q$]::text[], $q$Ciência que estuda o comportamento como relação entre o organismo e o ambiente, considerando a estrutura genética e a história de vida.$q$, $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Na clínica, procura entender em que situações um comportamento ocorre e quais consequências o mantêm, para então construir outras formas de agir. Sua base filosófica é o "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/glossario/behaviorismo-radical","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"behaviorismo radical"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Veja "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/perguntas/o-que-e-terapia-em-analise-do-comportamento","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"como a terapia em Análise do Comportamento funciona"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"."}]}]}}$q$::jsonb, $q$["Guimarães RP. Deixando o preconceito de lado e entendendo o Behaviorismo Radical. Psicol Cienc Prof. 2003;23(3). doi:10.1590/S1414-98932003000300009","Hanley GP, Iwata BA, McCord BE. Functional analysis of problem behavior: a review. J Appl Behav Anal. 2003;36(2):147-185. doi:10.1901/jaba.2003.36-147"]$q$::jsonb, 'published', now()) ON CONFLICT (slug) DO NOTHING;
INSERT INTO glossary_terms (slug, term, alt_names, short_definition, body, sources, status, published_at) VALUES ($q$behaviorismo-radical$q$, $q$Behaviorismo radical$q$, '{}'::text[], $q$Filosofia da Análise do Comportamento, associada a B. F. Skinner, que busca explicações em causas naturais e observáveis e trata o comportamento como relação com o ambiente.$q$, $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Ao contrário de uma ideia comum, a abordagem não ignora o que a pessoa sente ou pensa: esses fenômenos fazem parte da dimensão natural que ela procura estudar."}]}]}}$q$::jsonb, $q$["Guimarães RP. Deixando o preconceito de lado e entendendo o Behaviorismo Radical. Psicol Cienc Prof. 2003;23(3). doi:10.1590/S1414-98932003000300009"]$q$::jsonb, 'published', now()) ON CONFLICT (slug) DO NOTHING;
INSERT INTO glossary_terms (slug, term, alt_names, short_definition, body, sources, status, published_at) VALUES ($q$analise-funcional$q$, $q$Análise funcional$q$, '{}'::text[], $q$Método que busca identificar as variáveis que influenciam a ocorrência de um comportamento, em vez de olhar apenas para a sua forma.$q$, $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"A pesquisa em análise funcional se baseia na observação direta do comportamento em diferentes condições do ambiente. Na psicoterapia, a mesma lógica ajuda a perguntar: o que acontece antes, o que acontece depois e o que isso produz na vida da pessoa."}]}]}}$q$::jsonb, $q$["Hanley GP, Iwata BA, McCord BE. Functional analysis of problem behavior: a review. J Appl Behav Anal. 2003;36(2):147-185. doi:10.1901/jaba.2003.36-147"]$q$::jsonb, 'published', now()) ON CONFLICT (slug) DO NOTHING;
INSERT INTO glossary_terms (slug, term, alt_names, short_definition, body, sources, status, published_at) VALUES ($q$reforcamento$q$, $q$Reforçamento$q$, ARRAY[$q$Reforço$q$]::text[], $q$Processo em que as consequências de um comportamento tornam mais provável que a pessoa volte a se comportar de maneira semelhante no mesmo contexto.$q$, $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"O termo descreve um efeito sobre a frequência do comportamento, e não um prêmio ou um elogio. Algo só é chamado de reforçador se de fato produz esse efeito. É um dos processos estudados pela "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/glossario/analise-do-comportamento","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Análise do Comportamento"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"."}]}]}}$q$::jsonb, $q$["Guimarães RP. Deixando o preconceito de lado e entendendo o Behaviorismo Radical. Psicol Cienc Prof. 2003;23(3). doi:10.1590/S1414-98932003000300009"]$q$::jsonb, 'published', now()) ON CONFLICT (slug) DO NOTHING;
INSERT INTO glossary_terms (slug, term, alt_names, short_definition, body, sources, status, published_at) VALUES ($q$esquiva-experiencial$q$, $q$Esquiva experiencial$q$, ARRAY[$q$Evitação experiencial$q$]::text[], $q$Tentativa de escapar ou evitar emoções, pensamentos, memórias e outras experiências privadas, mesmo quando isso traz custos.$q$, $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"A revisão que propôs o conceito argumenta que muitas formas de sofrimento psicológico podem ser entendidas como esforços pouco saudáveis para fugir dessas experiências. Por isso, a psicoterapia pode incluir aprender a lidar com elas de outra forma."}]}]}}$q$::jsonb, $q$["Hayes SC et al. Experiential avoidance and behavioral disorders: a functional dimensional approach to diagnosis and treatment. J Consult Clin Psychol. 1996;64(6):1152-1168. doi:10.1037//0022-006x.64.6.1152"]$q$::jsonb, 'published', now()) ON CONFLICT (slug) DO NOTHING;
INSERT INTO glossary_terms (slug, term, alt_names, short_definition, body, sources, status, published_at) VALUES ($q$plantao-psicologico$q$, $q$Plantão psicológico$q$, '{}'::text[], $q$Modalidade clínica distinta da psicoterapia, voltada ao acolhimento de quem passa por um momento de crise.$q$, $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Não substitui um serviço de emergência. Em risco imediato, ligue para o SAMU (192) ou vá ao pronto-socorro mais próximo. Para conversar agora, o CVV atende pelo 188, 24 horas por dia."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Veja a página de "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/plantao","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"plantão psicológico"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"."}]}]}}$q$::jsonb, $q$["Amorim FBT, Andrade AB, Branco PCC. Plantão psicológico como estratégia de clínica ampliada na atenção básica em saúde. Contextos Clínicos. 2015;8(2):141-152. doi:10.4013/ctc.2015.82.03"]$q$::jsonb, 'published', now()) ON CONFLICT (slug) DO NOTHING;
INSERT INTO glossary_terms (slug, term, alt_names, short_definition, body, sources, status, published_at) VALUES ($q$psicoterapia-afirmativa-lgbtqia$q$, $q$Psicoterapia afirmativa LGBTQIA+$q$, ARRAY[$q$Terapia afirmativa$q$]::text[], $q$Psicoterapia que reconhece o impacto do preconceito sobre a saúde mental e não trata orientação sexual ou identidade de gênero como problema a ser corrigido.$q$, $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"O modelo de estresse de minoria explica como estigma, preconceito e discriminação criam um ambiente social estressante. Um ensaio clínico inicial com homens gays e bissexuais jovens encontrou redução de sintomas depressivos em comparação com a lista de espera, em uma amostra pequena (63 participantes)."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"No Brasil, a Resolução CFP nº 1/1999 determina que psicólogas e psicólogos não favoreçam a patologização de comportamentos ou práticas homoeróticas. Veja a página de "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/lgbtqia","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"atendimento LGBTQIA+"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"."}]}]}}$q$::jsonb, $q$["Meyer IH. Prejudice, social stress, and mental health in lesbian, gay, and bisexual populations: conceptual issues and research evidence. Psychol Bull. 2003;129(5):674-697. doi:10.1037/0033-2909.129.5.674","Pachankis JE et al. LGB-affirmative cognitive-behavioral therapy for young adult gay and bisexual men: a randomized controlled trial of a transdiagnostic minority stress approach. J Consult Clin Psychol. 2015;83(5):875-889. doi:10.1037/ccp0000037","Conselho Federal de Psicologia. Resolução CFP nº 1, de 22 de março de 1999: normas de atuação em relação à orientação sexual."]$q$::jsonb, 'published', now()) ON CONFLICT (slug) DO NOTHING;
INSERT INTO faq_questions (question, status, answer, slug, topic, published_at) VALUES ($q$O que é avaliação neuropsicológica?$q$, 'published', $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"A avaliação neuropsicológica é um processo estruturado que investiga funções cognitivas, como atenção, memória, linguagem e "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/glossario/funcoes-executivas","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"funções executivas"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":", por meio de entrevista e testes padronizados."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Os resultados são interpretados junto com a história de vida e a rotina da pessoa e registrados em um "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/glossario/laudo-psicologico","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"laudo"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":", apresentado em uma "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/glossario/devolutiva","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"sessão de devolutiva"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":". Revisões da literatura apontam que ela acrescenta informação útil ao cuidado, com evidência mais forte em comprometimento cognitivo leve, demência e traumatismo craniano."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Saiba mais sobre "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/avaliacao-neuropsicologica","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"a avaliação neuropsicológica na Vila Madalena"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Referências: Donders J. The incremental value of neuropsychological assessment: a critical review. Clin Neuropsychol. 2020;34(1):56-87. doi:10.1080/13854046.2019.1575471 Watt S, Crowe SF. Examining the beneficial effect of neuropsychological assessment on adult patient outcomes: a systematic review. Clin Neuropsychol. 2018;32(3):368-390. doi:10.1080/13854046.2017.1414885"}]}]}}$q$::jsonb, $q$o-que-e-avaliacao-neuropsicologica$q$, $q$avaliacao$q$, now() - interval '0 seconds') ON CONFLICT (slug) DO NOTHING;
INSERT INTO faq_questions (question, status, answer, slug, topic, published_at) VALUES ($q$Quanto tempo dura uma avaliação neuropsicológica?$q$, 'published', $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"A duração varia entre profissionais e conforme o caso. No consultório de João Fernandes, na Vila Madalena, a avaliação costuma levar de 4 a 6 sessões, de até 2 horas cada."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"O número exato depende das perguntas a responder e dos testes necessários. Veja "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/avaliacao-neuropsicologica","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"como é o processo"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"."}]}]}}$q$::jsonb, $q$quanto-tempo-dura-a-avaliacao-neuropsicologica$q$, $q$avaliacao$q$, now() - interval '1 seconds') ON CONFLICT (slug) DO NOTHING;
INSERT INTO faq_questions (question, status, answer, slug, topic, published_at) VALUES ($q$Quem pode fazer avaliação neuropsicológica?$q$, 'published', $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"No Brasil, o uso profissional de testes psicológicos é privativo de psicólogas e psicólogos, por isso a avaliação neuropsicológica baseada nesses testes é conduzida por esses profissionais."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"A "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/glossario/neuropsicologia","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Neuropsicologia"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":" é reconhecida pelo Conselho Federal de Psicologia como especialidade. Antes de agendar, vale perguntar sobre a formação do profissional na área e "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/perguntas/como-consultar-o-crp-de-um-psicologo","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"conferir o registro no CRP"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Referências: Conselho Federal de Psicologia. Resolução CFP nº 31, de 15 de dezembro de 2022: diretrizes para a avaliação psicológica e regulamentação do SATEPSI. Conselho Federal de Psicologia. Experiência brasileira em neuropsicologia é apresentada pelo CFP em congresso global (sobre a Resolução CFP nº 2/2004). site.cfp.org.br."}]}]}}$q$::jsonb, $q$quem-pode-fazer-avaliacao-neuropsicologica$q$, $q$avaliacao$q$, now() - interval '2 seconds') ON CONFLICT (slug) DO NOTHING;
INSERT INTO faq_questions (question, status, answer, slug, topic, published_at) VALUES ($q$Quando procurar uma avaliação neuropsicológica?$q$, 'published', $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"A avaliação costuma ser indicada quando há uma pergunta clínica sobre o funcionamento cognitivo, em geral a partir do encaminhamento de um médico ou de outro profissional."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Exemplos são queixas de memória, de atenção ou de aprendizagem, a investigação de condições do neurodesenvolvimento, o acompanhamento de mudanças depois de um traumatismo craniano ou de um AVC e a suspeita de "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/glossario/comprometimento-cognitivo-leve","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"comprometimento cognitivo leve"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":". Veja "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/avaliacao-neuropsicologica","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"outras situações"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Referências: Donders J. The incremental value of neuropsychological assessment: a critical review. Clin Neuropsychol. 2020;34(1):56-87. doi:10.1080/13854046.2019.1575471 Watt S, Crowe SF. Examining the beneficial effect of neuropsychological assessment on adult patient outcomes: a systematic review. Clin Neuropsychol. 2018;32(3):368-390. doi:10.1080/13854046.2017.1414885"}]}]}}$q$::jsonb, $q$quando-procurar-uma-avaliacao-neuropsicologica$q$, $q$avaliacao$q$, now() - interval '3 seconds') ON CONFLICT (slug) DO NOTHING;
INSERT INTO faq_questions (question, status, answer, slug, topic, published_at) VALUES ($q$A avaliação neuropsicológica diagnostica TDAH?$q$, 'published', $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Sozinha, não. Segundo o consenso internacional de 2021, o "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/glossario/tdah","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"TDAH"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":" só pode ser diagnosticado por um profissional habilitado que documenta os critérios clínicos em entrevista, e não apenas com escalas, testes neuropsicológicos ou exames de imagem."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"A avaliação pode contribuir para a investigação ao descrever pontos fortes e dificuldades da pessoa e levar essas informações ao profissional responsável pelo diagnóstico."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Referências: Faraone SV et al. The World Federation of ADHD International Consensus Statement: 208 evidence-based conclusions about the disorder. Neurosci Biobehav Rev. 2021;128:789-818. doi:10.1016/j.neubiorev.2021.01.022"}]}]}}$q$::jsonb, $q$a-avaliacao-neuropsicologica-diagnostica-tdah$q$, $q$avaliacao$q$, now() - interval '4 seconds') ON CONFLICT (slug) DO NOTHING;
INSERT INTO faq_questions (question, status, answer, slug, topic, published_at) VALUES ($q$Qual a diferença entre avaliação psicológica e avaliação neuropsicológica?$q$, 'published', $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"A avaliação psicológica é o processo estruturado de investigação de fenômenos psicológicos, feito para responder a uma demanda específica. A avaliação neuropsicológica dá ênfase às funções cognitivas e à relação delas com o funcionamento do cérebro."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Nas duas, os testes psicológicos seguem as regras do "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/glossario/satepsi","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"SATEPSI"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Referências: Conselho Federal de Psicologia. Resolução CFP nº 31, de 15 de dezembro de 2022: diretrizes para a avaliação psicológica e regulamentação do SATEPSI. Conselho Federal de Psicologia. Experiência brasileira em neuropsicologia é apresentada pelo CFP em congresso global (sobre a Resolução CFP nº 2/2004). site.cfp.org.br."}]}]}}$q$::jsonb, $q$qual-a-diferenca-entre-avaliacao-psicologica-e-neuropsicologica$q$, $q$avaliacao$q$, now() - interval '5 seconds') ON CONFLICT (slug) DO NOTHING;
INSERT INTO faq_questions (question, status, answer, slug, topic, published_at) VALUES ($q$O que vem no laudo de uma avaliação neuropsicológica?$q$, 'published', $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Pela Resolução CFP nº 6/2019, um laudo psicológico tem seis itens: identificação, descrição da demanda, procedimento, análise, conclusão e referências."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"A norma prevê a entrega em uma "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/glossario/devolutiva","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"entrevista devolutiva"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":", em que a pessoa pode esclarecer dúvidas sobre o documento."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Referências: Conselho Federal de Psicologia. Resolução CFP nº 6, de 29 de março de 2019: elaboração de documentos escritos."}]}]}}$q$::jsonb, $q$o-que-vem-no-laudo-de-uma-avaliacao-neuropsicologica$q$, $q$avaliacao$q$, now() - interval '6 seconds') ON CONFLICT (slug) DO NOTHING;
INSERT INTO faq_questions (question, status, answer, slug, topic, published_at) VALUES ($q$O plano de saúde cobre avaliação neuropsicológica?$q$, 'published', $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Depende do contrato, por isso a confirmação precisa vir da sua operadora, inclusive sobre quais documentos ela exige."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"João Fernandes não atende por convênio médico: a avaliação é uma consulta particular, com recibo para você solicitar o reembolso ao plano. "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/avaliacao-neuropsicologica","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Veja como funciona"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"."}]}]}}$q$::jsonb, $q$o-plano-de-saude-cobre-avaliacao-neuropsicologica$q$, $q$avaliacao$q$, now() - interval '7 seconds') ON CONFLICT (slug) DO NOTHING;
INSERT INTO faq_questions (question, status, answer, slug, topic, published_at) VALUES ($q$A avaliação neuropsicológica pode ser feita online?$q$, 'published', $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Depende dos instrumentos: a Resolução CFP nº 9/2024 exige que testes psicológicos usados por meios digitais tenham parecer favorável no SATEPSI, com padronização específica para essa finalidade."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"No consultório de João Fernandes, a avaliação neuropsicológica é realizada somente de forma presencial, na Vila Madalena."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Referências: Conselho Federal de Psicologia. Resolução CFP nº 9, de 18 de julho de 2024: exercício profissional mediado por tecnologias digitais."}]}]}}$q$::jsonb, $q$a-avaliacao-neuropsicologica-pode-ser-online$q$, $q$avaliacao$q$, now() - interval '8 seconds') ON CONFLICT (slug) DO NOTHING;
INSERT INTO faq_questions (question, status, answer, slug, topic, published_at) VALUES ($q$Crianças podem fazer avaliação neuropsicológica?$q$, 'published', $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Sim. A avaliação é usada ao longo de toda a vida, com instrumentos escolhidos de acordo com a idade e a demanda."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"No consultório de João Fernandes, ela é feita com adultos e crianças. Dificuldades de leitura, como a "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/glossario/dislexia","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"dislexia"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":", e questões escolares estão entre os motivos de procura. Veja "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/avaliacao-neuropsicologica","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"a página da avaliação"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Referências: Donders J. The incremental value of neuropsychological assessment: a critical review. Clin Neuropsychol. 2020;34(1):56-87. doi:10.1080/13854046.2019.1575471"}]}]}}$q$::jsonb, $q$criancas-podem-fazer-avaliacao-neuropsicologica$q$, $q$avaliacao$q$, now() - interval '9 seconds') ON CONFLICT (slug) DO NOTHING;
INSERT INTO faq_questions (question, status, answer, slug, topic, published_at) VALUES ($q$Onde fazer avaliação neuropsicológica na Vila Madalena?$q$, 'published', $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Uma opção é o consultório de João Vitor Fernandes Domingues, psicólogo, CRP 06/157908, com pós-graduação em Neuropsicologia pelo Hospital Israelita Albert Einstein, na Rua Harmonia, 1323, Sumarezinho, Vila Madalena, São Paulo."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"O atendimento é presencial, para adultos e crianças, de segunda a sexta, das 8h às 21h, com pedido médico. É uma consulta particular, com recibo para reembolso, e os valores são informados pelo WhatsApp. Veja "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/avaliacao-neuropsicologica","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"a página da avaliação"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"."}]}]}}$q$::jsonb, $q$onde-fazer-avaliacao-neuropsicologica-na-vila-madalena$q$, $q$avaliacao$q$, now() - interval '10 seconds') ON CONFLICT (slug) DO NOTHING;
INSERT INTO faq_questions (question, status, answer, slug, topic, published_at) VALUES ($q$Como funciona a psicoterapia?$q$, 'published', $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"A psicoterapia é um trabalho conjunto entre a pessoa e um profissional habilitado, em encontros regulares, para entender o que mantém o sofrimento e construir outras formas de lidar com ele."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Em geral, os primeiros encontros servem para conhecer a história e definir objetivos. A pesquisa mostra associação consistente entre a "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/glossario/alianca-terapeutica","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"aliança terapêutica"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":" e os resultados. O que é dito em sessão é protegido pelo sigilo profissional. Saiba mais sobre "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/psicoterapia","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"psicoterapia individual"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Referências: Flückiger C et al. The alliance in adult psychotherapy: a meta-analytic synthesis. Psychotherapy. 2018;55(4):316-340. doi:10.1037/pst0000172 Wampold BE. How important are the common factors in psychotherapy? An update. World Psychiatry. 2015;14(3):270-277. doi:10.1002/wps.20238"}]}]}}$q$::jsonb, $q$como-funciona-a-psicoterapia$q$, $q$psicoterapia$q$, now() - interval '11 seconds') ON CONFLICT (slug) DO NOTHING;
INSERT INTO faq_questions (question, status, answer, slug, topic, published_at) VALUES ($q$Quanto tempo dura a psicoterapia?$q$, 'published', $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Não existe um prazo fixo: a duração depende dos objetivos, da questão trabalhada e da decisão da própria pessoa."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Como referência, um estudo com mais de 100 mil pacientes em serviços do Reino Unido observou que 95% dos que melhoraram o fizeram em até 14 sessões de terapia cognitivo-comportamental de alta intensidade, com percursos mais longos em alguns quadros. Esse dado descreve uma abordagem e um contexto específicos e não prevê o resultado de cada pessoa."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Referências: Robinson L et al. Dose-response patterns in low and high intensity cognitive behavioral therapy for common mental health problems. Depress Anxiety. 2020;37(3):285-294. doi:10.1002/da.22999"}]}]}}$q$::jsonb, $q$quanto-tempo-dura-a-psicoterapia$q$, $q$psicoterapia$q$, now() - interval '12 seconds') ON CONFLICT (slug) DO NOTHING;
INSERT INTO faq_questions (question, status, answer, slug, topic, published_at) VALUES ($q$A psicoterapia funciona?$q$, 'published', $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"A pesquisa indica que sim para muitas pessoas, embora nenhum profissional possa prever o resultado de um caso específico."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Em depressão, uma meta-análise com 101 estudos e 11.910 pacientes não encontrou diferença significativa de resposta entre psicoterapia e medicação isoladas, e a combinação das duas teve resposta maior ao final do tratamento. Na ativação comportamental, derivada da Análise do Comportamento, uma meta-análise encontrou efeito favorável em relação a grupos controle, com a ressalva de que a qualidade da maioria dos estudos era baixa."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Não interrompa nem altere medicação sem falar com o médico que acompanha você."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Referências: Cuijpers P et al. A network meta-analysis of the effects of psychotherapies, pharmacotherapies and their combination in the treatment of adult depression. World Psychiatry. 2020;19(1):92-107. doi:10.1002/wps.20701 Ekers D et al. Behavioural activation for depression; an update of meta-analysis of effectiveness and sub group analysis. PLoS One. 2014;9(6):e100100. doi:10.1371/journal.pone.0100100"}]}]}}$q$::jsonb, $q$a-psicoterapia-funciona$q$, $q$psicoterapia$q$, now() - interval '13 seconds') ON CONFLICT (slug) DO NOTHING;
INSERT INTO faq_questions (question, status, answer, slug, topic, published_at) VALUES ($q$Terapia online funciona?$q$, 'published', $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"A pesquisa disponível é favorável: uma meta-análise de 31 ensaios clínicos com adultos encontrou efeitos semelhantes entre a terapia cognitivo-comportamental pela internet, com apoio de um terapeuta, e a presencial."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Outra meta-análise encontrou associação semelhante entre "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/glossario/alianca-terapeutica","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"aliança terapêutica"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":" e resultado nos dois formatos. Os dados vêm principalmente desse tipo de terapia e não valem automaticamente para todos os casos. No Brasil, o atendimento mediado por tecnologias digitais é regulamentado pela Resolução CFP nº 9/2024."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Em risco imediato, o atendimento online não substitui a emergência: ligue 192 (SAMU) ou 188 (CVV)."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Referências: Hedman-Lagerlöf E et al. Therapist-supported Internet-based cognitive behaviour therapy yields similar effects as face-to-face therapy for psychiatric and somatic disorders: an updated systematic review and meta-analysis. World Psychiatry. 2023;22(2):305-314. doi:10.1002/wps.21088 Flückiger C et al. The alliance in adult psychotherapy: a meta-analytic synthesis. Psychotherapy. 2018;55(4):316-340. doi:10.1037/pst0000172 Conselho Federal de Psicologia. Resolução CFP nº 9, de 18 de julho de 2024: exercício profissional mediado por tecnologias digitais."}]}]}}$q$::jsonb, $q$terapia-online-funciona$q$, $q$psicoterapia$q$, now() - interval '14 seconds') ON CONFLICT (slug) DO NOTHING;
INSERT INTO faq_questions (question, status, answer, slug, topic, published_at) VALUES ($q$O que é terapia em Análise do Comportamento?$q$, 'published', $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"É uma psicoterapia baseada na "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/glossario/analise-do-comportamento","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Análise do Comportamento"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":", que procura entender em que situações certos comportamentos, pensamentos e sentimentos ocorrem e o que os mantém."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"A partir dessa "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/glossario/analise-funcional","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"análise funcional"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":", a pessoa e o profissional constroem mudanças na rotina e nas relações. A abordagem considera o que a pessoa sente: esses fenômenos também fazem parte do que ela estuda. Saiba mais sobre "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/psicoterapia","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"psicoterapia individual"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Referências: Guimarães RP. Deixando o preconceito de lado e entendendo o Behaviorismo Radical. Psicol Cienc Prof. 2003;23(3). doi:10.1590/S1414-98932003000300009 Hanley GP, Iwata BA, McCord BE. Functional analysis of problem behavior: a review. J Appl Behav Anal. 2003;36(2):147-185. doi:10.1901/jaba.2003.36-147"}]}]}}$q$::jsonb, $q$o-que-e-terapia-em-analise-do-comportamento$q$, $q$psicoterapia$q$, now() - interval '15 seconds') ON CONFLICT (slug) DO NOTHING;
INSERT INTO faq_questions (question, status, answer, slug, topic, published_at) VALUES ($q$Como escolher um psicólogo?$q$, 'published', $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Comece confirmando que a pessoa tem registro ativo no Conselho Regional de Psicologia e pergunte sobre a abordagem, a formação e como é o atendimento."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Observe também se você se sente à vontade para conversar, já que a "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/glossario/alianca-terapeutica","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"aliança terapêutica"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":" está associada aos resultados. Desconfie de quem promete cura ou garante o resultado de antemão: as regras do Conselho Federal de Psicologia não permitem esse tipo de previsão na divulgação de serviços. Veja "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/perguntas/como-consultar-o-crp-de-um-psicologo","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"como consultar o CRP"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Referências: Flückiger C et al. The alliance in adult psychotherapy: a meta-analytic synthesis. Psychotherapy. 2018;55(4):316-340. doi:10.1037/pst0000172"}]}]}}$q$::jsonb, $q$como-escolher-um-psicologo$q$, $q$psicoterapia$q$, now() - interval '16 seconds') ON CONFLICT (slug) DO NOTHING;
INSERT INTO faq_questions (question, status, answer, slug, topic, published_at) VALUES ($q$Como consultar o CRP de um psicólogo?$q$, 'published', $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Use o Cadastro Nacional de Profissionais de Psicologia, do Conselho Federal de Psicologia, em cadastro.cfp.org.br, ou o site do Conselho Regional do estado em que a pessoa atua."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"O número do CRP deve aparecer na divulgação dos serviços, junto com o nome completo do profissional."}]}]}}$q$::jsonb, $q$como-consultar-o-crp-de-um-psicologo$q$, $q$psicoterapia$q$, now() - interval '17 seconds') ON CONFLICT (slug) DO NOTHING;
INSERT INTO faq_questions (question, status, answer, slug, topic, published_at) VALUES ($q$Qual a diferença entre psicólogo e psiquiatra?$q$, 'published', $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"O psicólogo tem graduação em Psicologia e registro no CRP. Trabalha com psicoterapia e avaliação psicológica e não prescreve medicamentos. O psiquiatra é médico com formação em psiquiatria, faz diagnóstico médico e pode prescrever medicamentos."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Os dois cuidados podem caminhar juntos: em depressão, por exemplo, a pesquisa encontrou resposta maior com a combinação de psicoterapia e medicação do que com cada uma isoladamente."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Referências: Cuijpers P et al. A network meta-analysis of the effects of psychotherapies, pharmacotherapies and their combination in the treatment of adult depression. World Psychiatry. 2020;19(1):92-107. doi:10.1002/wps.20701"}]}]}}$q$::jsonb, $q$qual-a-diferenca-entre-psicologo-e-psiquiatra$q$, $q$psicoterapia$q$, now() - interval '18 seconds') ON CONFLICT (slug) DO NOTHING;
INSERT INTO faq_questions (question, status, answer, slug, topic, published_at) VALUES ($q$Preciso de um diagnóstico para fazer terapia?$q$, 'published', $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Não. Muitas pessoas começam a psicoterapia sem um diagnóstico, por causa de um conflito, de uma mudança de vida ou de uma sensação de que algo precisa mudar."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Saiba mais sobre "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/autoconhecimento","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"autoconhecimento"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":" e "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/psicoterapia","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"psicoterapia individual"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":". Se houver sinais de sofrimento intenso, procure ajuda sem esperar por um diagnóstico."}]}]}}$q$::jsonb, $q$preciso-de-diagnostico-para-fazer-terapia$q$, $q$psicoterapia$q$, now() - interval '19 seconds') ON CONFLICT (slug) DO NOTHING;
INSERT INTO faq_questions (question, status, answer, slug, topic, published_at) VALUES ($q$O que fazer em uma crise emocional?$q$, 'published', $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Se houver risco imediato à sua vida ou à de outra pessoa, ligue para o SAMU (192) ou vá ao pronto-socorro mais próximo. Para conversar agora, o CVV atende pelo 188, 24 horas por dia, sem custo de ligação."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Se o risco não for imediato, avise alguém de confiança e não fique sozinho, se puder. Depois, um profissional pode ajudar a entender o que aconteceu e a planejar os próximos passos. Veja o que é o "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/plantao","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"plantão psicológico"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":", que não substitui um serviço de emergência."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Referências: Amorim FBT, Andrade AB, Branco PCC. Plantão psicológico como estratégia de clínica ampliada na atenção básica em saúde. Contextos Clínicos. 2015;8(2):141-152. doi:10.4013/ctc.2015.82.03"}]}]}}$q$::jsonb, $q$o-que-fazer-em-uma-crise-emocional$q$, $q$psicoterapia$q$, now() - interval '20 seconds') ON CONFLICT (slug) DO NOTHING;
INSERT INTO faq_questions (question, status, answer, slug, topic, published_at) VALUES ($q$O que é psicoterapia afirmativa LGBTQIA+?$q$, 'published', $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"É uma psicoterapia que reconhece os efeitos do preconceito sobre a saúde mental e não trata orientação sexual ou identidade de gênero como algo a ser corrigido."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"O "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/glossario/psicoterapia-afirmativa-lgbtqia","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"modelo de estresse de minoria"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":" explica como estigma e discriminação criam um ambiente social estressante. No Brasil, a Resolução CFP nº 1/1999 determina que psicólogas e psicólogos não favoreçam a patologização de comportamentos ou práticas homoeróticas. Saiba mais sobre o "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/lgbtqia","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"atendimento LGBTQIA+"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Referências: Meyer IH. Prejudice, social stress, and mental health in lesbian, gay, and bisexual populations: conceptual issues and research evidence. Psychol Bull. 2003;129(5):674-697. doi:10.1037/0033-2909.129.5.674 Conselho Federal de Psicologia. Resolução CFP nº 1, de 22 de março de 1999: normas de atuação em relação à orientação sexual."}]}]}}$q$::jsonb, $q$o-que-e-psicoterapia-afirmativa-lgbtqia$q$, $q$psicoterapia$q$, now() - interval '21 seconds') ON CONFLICT (slug) DO NOTHING;
INSERT INTO faq_questions (question, status, answer, slug, topic, published_at) VALUES ($q$Onde encontrar psicólogo em Análise do Comportamento na Vila Madalena?$q$, 'published', $q${"root":{"type":"root","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Uma opção é o consultório de João Vitor Fernandes Domingues, psicólogo, CRP 06/157908, com atuação em Análise do Comportamento desde 2019, na Rua Harmonia, 1323, Sumarezinho, Vila Madalena, São Paulo."}]},{"type":"paragraph","version":1,"format":"","indent":0,"direction":null,"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"Ele atende adultos presencialmente e também online, para todo o Brasil, de segunda a sexta, das 8h às 21h. O atendimento é particular, com recibo para reembolso, e o contato é pelo WhatsApp. Veja "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/psicoterapia","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"psicoterapia individual"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":" e "},{"type":"link","version":1,"format":"","indent":0,"direction":null,"fields":{"url":"/presencial","linkType":"custom","newTab":false},"children":[{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"como chegar"}]},{"type":"text","version":1,"format":0,"mode":"normal","style":"","detail":0,"text":"."}]}]}}$q$::jsonb, $q$onde-encontrar-psicologo-em-analise-do-comportamento-na-vila-madalena$q$, $q$psicoterapia$q$, now() - interval '22 seconds') ON CONFLICT (slug) DO NOTHING;
